from functools import reduce
from operator import add

def solve(n, weights):
    counts = [0] * (n + 1)
    for w in weights:
        for i in range(n, 0, -1):
            if w >= i:
                counts[i] += 1
                w -= i
    a = [0] * n
    for i in range(1, n + 1):
        a[i - 1] = reduce(add, [x * (counts[i] // x) for x in range(1, i + 1)], 0)
    if any(a[i] > w for w in weights):
        return 'impossible'
    return '\n'.join(map(str, a))

